        t3Body: "استخدم الأماكن المحفوظة أو حدّد موقعي أو ضع دبوسًا لجعل نقاط الانطلاق واضحة. تساعد نقطة الانطلاق الواضحة المشغّل الصحيح على إيجادك وتقلّل الالتباس. عند الإمكان، انتظر في مكان مضاء وبه أشخاص قريبون ومسار واضح للمغادرة إذا شعرت بأي خطأ.",
        t4Title: "أثناء الرحلة",
        t4Body: "أبقِ هاتفك متاحًا، وراقب المسار، وتحدّث مبكرًا إذا تغيّر المسار دون تفسير. لا تشارك كلمات مرور خاصة أو أرقام PIN أو رموز OTP أو تفاصيل البطاقة الكاملة أو معلومات شخصية حسّاسة. إذا أصبح المشغّل غير آمن، اطلب التوقّف في مكان عام عندما يكون ذلك آمنًا.",
        t5Title: "إجراء الطوارئ",
        t5Body: "في حالة الخطر المباشر، اتصل أولًا بخدمات الطوارئ المحلية. بعد الاتصال بالمساعدة، استخدم دعم KunThai لتسجيل الرحلة والمشغّل والموقع والوقت والمسار وما حدث. يساعد سجل التطبيق في المتابعة، لكن يجب أن يأتي المستجيبون للطوارئ والأشخاص الموثوقون القريبون أولًا.",
        t6Title: "شارك الإثبات والموقع",
        t6Body: "قبل الرحلة أو أثناءها، شارك مسارك واسم المشغّل ورقم اللوحة وتفاصيل الانطلاق أو الوجهة مع شخص تثق به. إذا بدت الرحلة غير عادية، أرسل رسالة قصيرة بموقعك الحالي وما يحدث قبل أن تصبح البطارية أو الإشارة مشكلة.",
        t7Title: "سلامة الأجرة والدفع",
        t7Body: "اتفق على طريقة الأجرة قبل بدء الرحلة. احتفظ بإثبات الدفع عند تبادل المال. في حال وجود خلاف على الأجرة، تجنّب الجدال في مكان غير آمن؛ سجّل التفاصيل وأبلغ عبر الدعم بعد أن تكون بأمان.",
        t8Title: "سلامة التوصيل",
        t8Body: "للتوصيل، تأكّد من اسم المستلم ورقم الهاتف وعنوان الانطلاق وعنوان النزول ووصف الغرض ومسؤولية الدفع. لا ترسل عناصر محظورة أو خطرة أو غير واضحة. استخدم الصور أو الملاحظات عندما تكون نقطة الانطلاق أو التوصيل مربكة.",
        t9Title: "الإبلاغ عن المشكلات",
        t9Body: "أبلغ عن القيادة غير الآمنة أو التحرّش أو التهديدات أو الأسطول المتضرّر أو المشغّل الخاطئ أو تغييرات المسار المريبة أو مشكلات التوصيل أو نزاعات الدفع بأكبر قدر من التفاصيل. تتضمّن التقارير الجيدة الوقت والمسار ورقم اللوحة واسم المشغّل ولقطات الشاشة والصور حيثما كان آمنًا ووصفًا هادئًا لما حدث.",
