      v1Body: "La verificación UrRide puede requerir una identificación emitida por el gobierno, licencia de conducir o de pasajero, registro del vehículo, seguro, registro de aptitud para la circulación, fotografías de la flota y otros documentos que se aplican en el país seleccionado.",
      v2Title: "Regístrese primero, complete la verificación después",
      v2Body: "Un operador en solitario puede continuar sin todos los documentos y cargar los archivos que faltan más tarde. Hasta que se complete la revisión, la cuenta permanecerá No verificada y los pasajeros deben tratarla con especial precaución.",
      v3Title: "La aprobación es una señal de seguridad",
      v3Body: "El estado verificado o recomendado significa que KunThai revisó la información requerida. No reemplaza el criterio de los pasajeros, la seguridad vial, las leyes locales ni los servicios de emergencia.",
      beforeTitle: "Antes de que cualquier pasajero entre a un vehículo",
      beforeBody: "Confirme el operador, número de placa, tipo de flota, punto de recogida, destino, tarifa y asientos disponibles antes de que comience el viaje.",
      o1Title: "Operadores solitarios",
      o1Body: "Utilice su identidad real, número de teléfono accesible, área de servicio correcta, licencia activa, precios honestos y la flota real que verán los pasajeros.",
      o2Title: "Detalles de flota y vehículos",
      o2Body: "Las fotografías de la flota, los números de placas, la información de los asientos y las respuestas de seguridad deben coincidir con el vehículo utilizado para los viajes o las entregas.",
      o3Title: "cuentas de empresa",
      o3Body: "Una empresa registra la organización y las flotas, luego invita a los operadores mediante el KunThai ID público de cada operador. Los operadores mantienen sus propias cuentas y nunca deben compartir una contraseña.",
      security: "No ingrese a un vehículo cuando el operador, flota, placa o ruta difiera de la aplicación. Muévase a un lugar público, cancele la solicitud y utilice herramientas de seguridad o apoyo cuando sienta que algo anda mal."
