        st1Title: "KunThai 可以做什么",
        st1Body: "KunThai 可以为运营商提供更好的指导、路线背景、行程记录、乘客请求详细信息、安全提醒和报告工具。 KunThai 无法保护操作员或乘客、控制道路状况或替代紧急服务。当涉及生命、健康、暴力、火灾、碰撞或严重危险时，紧急援助和附近值得信赖的人必须首先出现。",
        st2Title: "接受前的专业义务",
        st2Body: "仅接受您可以安全完成的行程。检查取货点、目的地、车队类型、乘客数量、包裹详细信息以及任何特殊说明。如果行程超出您的服务区域、对您的车队不安全、超载或不清楚，请勿仅仅为了赢得请求而接受行程。",
        st3Title: "抵达协议",
        st3Body: "到达预订中显示的接载点，冷静地表明身份，并让乘客确认您的运营商名称、车队类型和车牌号。如果乘客仍在检查详细信息，请勿强迫他们进入。专业的操作员让乘客在旅行开始前感到安全。",
        st4Title: "乘客尊重和界限",
        st4Body: "避免骚扰、侮辱、威胁、激进的讨价还价或不必要的个人问题。让沟通重点关注取货、路线、票价、送货和安全。如果乘客感到苦恼、困惑、年老、残疾或携带儿童旅行，请放慢互动速度并明确流程。",
        st5Title: "路线纪律",
        st5Body: "遵循商定的路线或区域视图中显示的路线，除非交通、道路封闭、危险或乘客指示需要更改。如果您必须更改路线，请在更改之前或更改后立即进行解释。突然不明原因的绕行会产生恐惧，并可能成为安全报告。",
        st6Title: "应急处理",
        st6Body: "发生碰撞、医疗问题、暴力、火灾、抢劫或严重道路危险时，请在最安全的地方停车，联系当地紧急救援人员，并在保护行程记录之前保护人员。联系紧急帮助后，记录行程详细信息、乘客姓名、地点、时间以及发生的情况，以便支持跟进。",
        st7Title: "冲突和票价分歧",
        st7Body: "不要在路边使争吵升级。如果发生票价、路线或运送方面的分歧，请保持低调，尽可能转移到公共且更安全的地方，并保留行程详细信息。支持人员可以更好地理解平静的报告，而不是缺乏事实的激烈争论。",
        st8Title: "配送安全",
        st8Body: "搬家前检查包裹描述、取件人、收件人详细信息、付款责任和投递地点。请勿携带可疑、危险、非法、泄漏或描述不明确的物品。如果无法验证收件人，请记录问题并联系支持人员，而不是在没有记录的情况下放弃包裹。",
        st9Title: "作为操作员报告",
